CREATE TABLE IF NOT EXISTS cfg_enterprise_model_grants (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,enterprise_id BIGINT UNSIGNED NOT NULL,writing_model_id BIGINT UNSIGNED NOT NULL,enabled BOOLEAN NOT NULL DEFAULT TRUE,is_default BOOLEAN NOT NULL DEFAULT FALSE,quota BIGINT NOT NULL DEFAULT 0,created_at DATETIME(6) NOT NULL,updated_at DATETIME(6) NOT NULL,deleted_at DATETIME(6),PRIMARY KEY(id),UNIQUE KEY uk_cfg_enterprise_model(enterprise_id,writing_model_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS cfg_enterprise_channel_grants (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,enterprise_id BIGINT UNSIGNED NOT NULL,publish_channel_id BIGINT UNSIGNED NOT NULL,enabled BOOLEAN NOT NULL DEFAULT TRUE,daily_limit BIGINT NOT NULL DEFAULT 0,created_at DATETIME(6) NOT NULL,updated_at DATETIME(6) NOT NULL,deleted_at DATETIME(6),PRIMARY KEY(id),UNIQUE KEY uk_cfg_enterprise_channel(enterprise_id,publish_channel_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS cfg_enterprise_site_grants (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,enterprise_id BIGINT UNSIGNED NOT NULL,inclusion_site_id BIGINT UNSIGNED NOT NULL,enabled BOOLEAN NOT NULL DEFAULT TRUE,daily_limit BIGINT NOT NULL DEFAULT 0,concurrency INT UNSIGNED NOT NULL DEFAULT 1,created_at DATETIME(6) NOT NULL,updated_at DATETIME(6) NOT NULL,deleted_at DATETIME(6),PRIMARY KEY(id),UNIQUE KEY uk_cfg_enterprise_site(enterprise_id,inclusion_site_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS cfg_system_settings (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,namespace VARCHAR(64) NOT NULL,key_name VARCHAR(128) NOT NULL,value_json JSON NOT NULL,description VARCHAR(1024),is_sensitive BOOLEAN NOT NULL DEFAULT FALSE,version BIGINT UNSIGNED NOT NULL DEFAULT 1,created_at DATETIME(6) NOT NULL,updated_at DATETIME(6) NOT NULL,deleted_at DATETIME(6),PRIMARY KEY(id),UNIQUE KEY uk_cfg_setting(namespace,key_name)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS cnt_brands (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,enterprise_id BIGINT UNSIGNED NOT NULL,name VARCHAR(128) NOT NULL,aliases_json JSON,official_domain VARCHAR(255),description LONGTEXT,industry VARCHAR(128),region VARCHAR(128),target_audience TEXT,core_value TEXT,status VARCHAR(32) NOT NULL,version BIGINT UNSIGNED NOT NULL DEFAULT 1,created_at DATETIME(6) NOT NULL,updated_at DATETIME(6) NOT NULL,deleted_at DATETIME(6),PRIMARY KEY(id),KEY idx_cnt_brand_tenant(enterprise_id,status,created_at),KEY idx_cnt_brand_domain(official_domain)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS cnt_products (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,enterprise_id BIGINT UNSIGNED NOT NULL,brand_id BIGINT UNSIGNED NOT NULL,name VARCHAR(255) NOT NULL,description LONGTEXT,selling_points_json JSON,target_audience TEXT,status VARCHAR(32) NOT NULL,created_at DATETIME(6) NOT NULL,updated_at DATETIME(6) NOT NULL,deleted_at DATETIME(6),PRIMARY KEY(id),KEY idx_cnt_product_tenant_brand(enterprise_id,brand_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS cnt_competitors (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,enterprise_id BIGINT UNSIGNED NOT NULL,brand_id BIGINT UNSIGNED NOT NULL,name VARCHAR(128) NOT NULL,aliases_json JSON,domains_json JSON,description TEXT,status VARCHAR(32) NOT NULL,created_at DATETIME(6) NOT NULL,updated_at DATETIME(6) NOT NULL,deleted_at DATETIME(6),PRIMARY KEY(id),KEY idx_cnt_competitor_tenant_brand(enterprise_id,brand_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS cnt_brand_terms (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,enterprise_id BIGINT UNSIGNED NOT NULL,brand_id BIGINT UNSIGNED NOT NULL,term_type VARCHAR(32) NOT NULL,term VARCHAR(255) NOT NULL,replacement VARCHAR(255),description VARCHAR(1024),enabled BOOLEAN NOT NULL DEFAULT TRUE,created_at DATETIME(6) NOT NULL,updated_at DATETIME(6) NOT NULL,deleted_at DATETIME(6),PRIMARY KEY(id),KEY idx_cnt_term_tenant_brand(enterprise_id,brand_id,term_type)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS cnt_keywords (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,enterprise_id BIGINT UNSIGNED NOT NULL,brand_id BIGINT UNSIGNED NOT NULL,text VARCHAR(255) NOT NULL,tags_json JSON,priority INT NOT NULL DEFAULT 0,status VARCHAR(32) NOT NULL,source VARCHAR(32) NOT NULL,version BIGINT UNSIGNED NOT NULL DEFAULT 1,created_at DATETIME(6) NOT NULL,updated_at DATETIME(6) NOT NULL,deleted_at DATETIME(6),PRIMARY KEY(id),KEY idx_cnt_keyword_tenant(enterprise_id,status,priority),KEY idx_cnt_keyword_brand(brand_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS cnt_questions (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,enterprise_id BIGINT UNSIGNED NOT NULL,keyword_id BIGINT UNSIGNED NOT NULL,brand_id BIGINT UNSIGNED NOT NULL,text TEXT NOT NULL,status VARCHAR(32) NOT NULL,intent VARCHAR(64),audience VARCHAR(128),funnel_stage VARCHAR(64),cluster_code VARCHAR(128),priority INT NOT NULL DEFAULT 0,sort_order INT NOT NULL DEFAULT 0,version BIGINT UNSIGNED NOT NULL DEFAULT 1,created_at DATETIME(6) NOT NULL,updated_at DATETIME(6) NOT NULL,deleted_at DATETIME(6),PRIMARY KEY(id),KEY idx_cnt_question_tenant(enterprise_id,status,priority),KEY idx_cnt_question_keyword(keyword_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS cnt_question_versions (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,enterprise_id BIGINT UNSIGNED NOT NULL,question_id BIGINT UNSIGNED NOT NULL,version_number INT UNSIGNED NOT NULL,text TEXT NOT NULL,metadata_json JSON,operator_type VARCHAR(32) NOT NULL,operator_id BIGINT UNSIGNED NOT NULL,reason VARCHAR(512),created_at DATETIME(6) NOT NULL,PRIMARY KEY(id),KEY idx_cnt_question_version(question_id,version_number)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS cnt_articles (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,enterprise_id BIGINT UNSIGNED NOT NULL,brand_id BIGINT UNSIGNED NOT NULL,article_type_id BIGINT UNSIGNED,title VARCHAR(512) NOT NULL,summary TEXT,content_markdown LONGTEXT,content_html LONGTEXT,status VARCHAR(32) NOT NULL,source VARCHAR(32) NOT NULL,current_version_id BIGINT UNSIGNED,latest_snapshot_id BIGINT UNSIGNED,quality_score DECIMAL(6,3) NOT NULL DEFAULT 0,quality_result_json JSON,published_at DATETIME(6),version BIGINT UNSIGNED NOT NULL DEFAULT 1,created_at DATETIME(6) NOT NULL,updated_at DATETIME(6) NOT NULL,deleted_at DATETIME(6),PRIMARY KEY(id),KEY idx_cnt_article_tenant_status(enterprise_id,status,created_at),KEY idx_cnt_article_brand(brand_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS cnt_article_versions (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,enterprise_id BIGINT UNSIGNED NOT NULL,article_id BIGINT UNSIGNED NOT NULL,version_number INT UNSIGNED NOT NULL,title VARCHAR(512) NOT NULL,summary TEXT,content_markdown LONGTEXT,content_html LONGTEXT,change_source VARCHAR(32) NOT NULL,change_summary VARCHAR(1024),operator_type VARCHAR(32) NOT NULL,operator_id BIGINT UNSIGNED NOT NULL,content_hash CHAR(64) NOT NULL,created_at DATETIME(6) NOT NULL,PRIMARY KEY(id),UNIQUE KEY uk_cnt_article_version(article_id,version_number),KEY idx_cnt_article_version_tenant(enterprise_id,article_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS cnt_article_reviews (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,enterprise_id BIGINT UNSIGNED NOT NULL,article_id BIGINT UNSIGNED NOT NULL,action VARCHAR(32) NOT NULL,from_status VARCHAR(32) NOT NULL,to_status VARCHAR(32) NOT NULL,reviewer_type VARCHAR(32) NOT NULL,reviewer_id BIGINT UNSIGNED NOT NULL,reason TEXT,created_at DATETIME(6) NOT NULL,PRIMARY KEY(id),KEY idx_cnt_article_review(enterprise_id,article_id,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS cnt_article_snapshots (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,enterprise_id BIGINT UNSIGNED NOT NULL,article_id BIGINT UNSIGNED NOT NULL,article_version_id BIGINT UNSIGNED NOT NULL,article_type_version_id BIGINT UNSIGNED,prompt_version_id BIGINT UNSIGNED,writing_model_id BIGINT UNSIGNED,title VARCHAR(512) NOT NULL,content_markdown LONGTEXT,content_html LONGTEXT,input_snapshot_json JSON,knowledge_refs_json JSON,content_hash CHAR(64) NOT NULL,created_at DATETIME(6) NOT NULL,PRIMARY KEY(id),KEY idx_cnt_snapshot_tenant_article(enterprise_id,article_id),KEY idx_cnt_snapshot_hash(content_hash)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS sec_platform_accounts (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,enterprise_id BIGINT UNSIGNED NOT NULL,resource_type VARCHAR(32) NOT NULL,resource_id BIGINT UNSIGNED NOT NULL,account_name VARCHAR(255) NOT NULL,external_id VARCHAR(255),masked_identity VARCHAR(255),authorization_status VARCHAR(32) NOT NULL,usage_status VARCHAR(32) NOT NULL,expires_at DATETIME(6),last_verified_at DATETIME(6),last_used_at DATETIME(6),daily_limit BIGINT NOT NULL DEFAULT 0,is_default BOOLEAN NOT NULL DEFAULT FALSE,metadata_json JSON,version BIGINT UNSIGNED NOT NULL DEFAULT 1,created_at DATETIME(6) NOT NULL,updated_at DATETIME(6) NOT NULL,deleted_at DATETIME(6),PRIMARY KEY(id),KEY idx_sec_account_tenant_resource(enterprise_id,resource_type,resource_id),KEY idx_sec_account_status(authorization_status,expires_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS sec_credential_envelopes (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,enterprise_id BIGINT UNSIGNED NOT NULL,platform_account_id BIGINT UNSIGNED NOT NULL,key_id VARCHAR(128) NOT NULL,algorithm VARCHAR(64) NOT NULL,ciphertext LONGBLOB NOT NULL,nonce VARBINARY(64) NOT NULL,aad_hash CHAR(64) NOT NULL,envelope_version INT UNSIGNED NOT NULL,status VARCHAR(32) NOT NULL,expires_at DATETIME(6),destroyed_at DATETIME(6),created_at DATETIME(6) NOT NULL,PRIMARY KEY(id),KEY idx_sec_envelope_account(enterprise_id,platform_account_id,status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS sec_authorization_sessions (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,enterprise_id BIGINT UNSIGNED NOT NULL,session_token_hash CHAR(64) NOT NULL,device_id VARCHAR(128) NOT NULL,resource_type VARCHAR(32) NOT NULL,resource_id BIGINT UNSIGNED NOT NULL,platform_account_id BIGINT UNSIGNED,status VARCHAR(32) NOT NULL,expires_at DATETIME(6) NOT NULL,completed_at DATETIME(6),client_version VARCHAR(64),version BIGINT UNSIGNED NOT NULL DEFAULT 1,created_at DATETIME(6) NOT NULL,updated_at DATETIME(6) NOT NULL,deleted_at DATETIME(6),PRIMARY KEY(id),UNIQUE KEY uk_sec_auth_session_token(session_token_hash),KEY idx_sec_auth_session_tenant(enterprise_id,status,expires_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
